import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

const Uploads = () => {
  const navigate = useNavigate();
  const [patientName, setPatientName] = useState("");
  const [patientId, setPatientId] = useState("");
  const [gender, setGender] = useState("Male");
  const [age, setAge] = useState("");
  const [date, setDate] = useState("");
  const [image, setImage] = useState(null);

  const handleImageChange = (e) => {
    if (e.target.files && e.target.files[0]) {
      setImage(URL.createObjectURL(e.target.files[0]));
    }
  };

  const handleScan = (e) => {
    e.preventDefault();
    if (!image) {
      alert("Please upload an image before scanning!");
      return;
    }
    navigate("/Analysis", {
      state: { patientName, patientId, gender, age, date, image },
    });
  };

  return (
    <div className="font-sans flex flex-col items-center bg-[#0B0F1A] text-[#E0E6F0] min-h-screen p-5">
      <h1 className="text-3xl font-bold text-white font-bold mb-8 text-center">
        Upload Medical Image
      </h1>

      {/* Image Upload Section */}
      <div className="mb-8 flex flex-col items-center w-full max-w-md">
        <div className="text-center mb-4">
          <h2 className="text-xl font-bold text-white bg-[#152033] p-3 rounded-t-md">
            Upload X-ray Images
          </h2>
          <p className="text-white bg-[#152033] p-2 rounded-b-md font-medium">
            Upload single or multiple images to perform scanning
          </p>
        </div>

        {image ? (
          <img
            src={image}
            alt="Uploaded"
            className="w-full rounded-md border-2 border-dashed border-[#00B0FF]"
          />
        ) : (
          <div className="w-full h-64 border-2 border-dashed border-[#00B0FF] rounded-md bg-[#111827] flex flex-col items-center justify-center cursor-pointer hover:bg-[#1B263B] transition-colors relative">
            <label className="flex flex-col items-center justify-center w-full h-full cursor-pointer">
              <input
                type="file"
                accept="image/*"
                onChange={handleImageChange}
                className="hidden"
                multiple
              />
              <div className="absolute bottom-4 text-center">
                <p className="text-[#00B0FF] font-medium">
                  Drag and drop or{" "}
                  <span className="underline cursor-pointer">Choose image</span>
                </p>
              </div>
            </label>
          </div>
        )}
      </div>

      {/* Patient Information Section */}
      <div className="w-full max-w-md text-center mb-4">
        <h2 className="text-xl font-semibold text-white font-bold mb-2">
          Patient Information
        </h2>
        <h3 className=" text-xl font-"></h3>
      </div>

      {/* Patient Info Form */}
      <form
        onSubmit={handleScan}
        className="max-w-md w-full flex flex-col gap-4 bg-[#152033] p-6 rounded-md shadow-lg border border-[#1E2A40]"
      >
        <input
          type="text"
          placeholder="Patient Name"
          value={patientName}
          onChange={(e) => setPatientName(e.target.value)}
          className="p-3 rounded-md bg-[#0F172A] border border-[#1E2A40] text-[#E0E6F0] placeholder-[#9CA3AF] focus:outline-none focus:ring-2 focus:ring-[#00B0FF]"
          required
        />
        <input
          type="text"
          placeholder="Patient ID"
          value={patientId}
          onChange={(e) => setPatientId(e.target.value)}
          className="p-3 rounded-md bg-[#0F172A] border border-[#1E2A40] text-[#E0E6F0] placeholder-[#9CA3AF] focus:outline-none focus:ring-2 focus:ring-[#00B0FF]"
          required
        />
        <select
          value={gender}
          onChange={(e) => setGender(e.target.value)}
          className="p-3 rounded-md bg-[#0F172A] border border-[#1E2A40] text-[#E0E6F0] focus:outline-none focus:ring-2 focus:ring-[#00B0FF]"
        >
          <option value="Male" className="bg-[#0B0F1A]">
            Male
          </option>
          <option value="Female" className="bg-[#0B0F1A]">
            Female
          </option>
        </select>
        <input
          type="number"
          placeholder="Age"
          value={age}
          onChange={(e) => setAge(e.target.value)}
          className="p-3 rounded-md bg-[#0F172A] border border-[#1E2A40] text-[#E0E6F0] placeholder-[#9CA3AF] focus:outline-none focus:ring-2 focus:ring-[#00B0FF]"
          required
        />
        <input
          type="date"
          value={date}
          onChange={(e) => setDate(e.target.value)}
          className="p-3 rounded-md bg-[#0F172A] border border-[#1E2A40] text-[#E0E6F0] focus:outline-none focus:ring-2 focus:ring-[#00B0FF]"
          required
        />

        <button
          type="submit"
          className="bg-green-600 text-white font-semibold p-3 rounded-md hover: transition-colors"
        >
          Scan
        </button>
      </form>
    </div>
  );
};

export default Uploads;
